import{_ as a,o as s,c as n,a3 as t}from"./chunks/framework.CpLciM8b.js";const u=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/architecture.md","filePath":"concepts/architecture.md","lastUpdated":1785494959000}'),r={name:"concepts/architecture.md"};function o(i,e,l,p,c,d){return s(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>Flakemetry is a layered, event-driven platform with one governing constraint: <strong>ingestion never blocks CI</strong> (ADR-0004). This document is the code-adjacent architecture reference; deeper product context lives in the <a href="https://github.com/AKogut/flakemetry/wiki" target="_blank" rel="noreferrer">wiki</a>.</p><h2 id="system-overview" tabindex="-1">System overview <a class="header-anchor" href="#system-overview" aria-label="Permalink to &quot;System overview&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  INGESTION EDGE                                                        │</span></span>
<span class="line"><span>│  @flakemetry/playwright-reporter · OTLP endpoint · GitHub Action       │</span></span>
<span class="line"><span>└────────────┬───────────────────────────────────────────────────────────┘</span></span>
<span class="line"><span>             │  OTLP/HTTP JSON (ADR-0002), idempotency key per run</span></span>
<span class="line"><span>             ▼</span></span>
<span class="line"><span>┌──────────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  INGESTION API  (apps/api)                                             │</span></span>
<span class="line"><span>│  authenticate → validate against contracts → enqueue → 202            │</span></span>
<span class="line"><span>└────────────┬───────────────────────────────────────────────────────────┘</span></span>
<span class="line"><span>             ▼  durable queue: Postgres FOR UPDATE SKIP LOCKED (ADR-0004)</span></span>
<span class="line"><span>┌──────────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  WORKERS  (apps/worker)                                                │</span></span>
<span class="line"><span>│  normalize spans → resolve test identity → update flaky score         │</span></span>
<span class="line"><span>│  → cluster failure signature → trigger AI RCA (async, budget-gated)   │</span></span>
<span class="line"><span>└────────────┬───────────────────────────────────────────────────────────┘</span></span>
<span class="line"><span>             ▼</span></span>
<span class="line"><span>┌──────────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  STORAGE                                                               │</span></span>
<span class="line"><span>│  PostgreSQL: relational core + JSONB + rollups   (packages/db)        │</span></span>
<span class="line"><span>│  S3/MinIO: artifacts (screenshots, videos, traces)                    │</span></span>
<span class="line"><span>└────────────┬───────────────────────────────────────────────────────────┘</span></span>
<span class="line"><span>             ▼</span></span>
<span class="line"><span>┌──────────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  QUERY API (tRPC/REST)  →  DASHBOARD (apps/web)                       │</span></span>
<span class="line"><span>└──────────────────────────────────────────────────────────────────────┘</span></span></code></pre></div><h2 id="data-flow" tabindex="-1">Data flow <a class="header-anchor" href="#data-flow" aria-label="Permalink to &quot;Data flow&quot;">​</a></h2><ol><li>A reporter emits OTel spans per the test semantic conventions and exports OTLP/HTTP with a per-run idempotency key.</li><li><code>apps/api</code> authenticates the project token, validates the payload against <code>@flakemetry/contracts</code>, enqueues it and ACKs <code>202</code> immediately.</li><li><code>apps/worker</code> dequeues with <code>SKIP LOCKED</code>, materializes <code>run</code> and <code>test_execution</code> rows, resolves the stable test identity, incrementally updates the flaky score (ADR-0003) and clusters the failure signature.</li><li>New failure signatures trigger asynchronous, budget-gated AI root-cause analysis; known signatures reuse the cached report at zero cost.</li><li>The dashboard reads through the typed query API, hitting rollups rather than raw executions for trends.</li></ol><h2 id="workspace-map" tabindex="-1">Workspace map <a class="header-anchor" href="#workspace-map" aria-label="Permalink to &quot;Workspace map&quot;">​</a></h2><p>The map of every app and package, with what each one does and which ones are published, is kept in one place: the <a href="https://akogut.github.io/flakemetry/contributing/development#where-things-live" target="_blank" rel="noreferrer">development guide</a>. A test fails when it misses a workspace or marks one published that is not.</p><p>Dependency direction is strictly downward: apps depend on packages, packages depend on <code>contracts</code>, nothing depends on apps.</p><h2 id="load-bearing-decisions" tabindex="-1">Load-bearing decisions <a class="header-anchor" href="#load-bearing-decisions" aria-label="Permalink to &quot;Load-bearing decisions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Decision</th><th>Record</th></tr></thead><tbody><tr><td>Monorepo: pnpm workspaces + Turborepo, contracts as shared source of truth</td><td><a href="https://github.com/AKogut/flakemetry/blob/main/docs/adr/0001-monorepo-pnpm-turborepo.md" target="_blank" rel="noreferrer">ADR-0001</a></td></tr><tr><td>OTel-native ingestion, tests as traces</td><td><a href="https://github.com/AKogut/flakemetry/blob/main/docs/adr/0002-otel-native-ingestion.md" target="_blank" rel="noreferrer">ADR-0002</a></td></tr><tr><td>Explainable statistical flaky scoring, no black-box ML</td><td><a href="https://github.com/AKogut/flakemetry/blob/main/docs/adr/0003-explainable-flaky-scoring.md" target="_blank" rel="noreferrer">ADR-0003</a></td></tr><tr><td>Async ingestion: 202 + durable Postgres queue</td><td><a href="https://github.com/AKogut/flakemetry/blob/main/docs/adr/0004-async-ingestion-202-queue.md" target="_blank" rel="noreferrer">ADR-0004</a></td></tr></tbody></table><p>New load-bearing decisions require a new ADR from <a href="https://github.com/AKogut/flakemetry/blob/main/docs/adr/template.md" target="_blank" rel="noreferrer">the template</a>; superseded decisions are marked, never deleted.</p><h2 id="cross-cutting-rules" tabindex="-1">Cross-cutting rules <a class="header-anchor" href="#cross-cutting-rules" aria-label="Permalink to &quot;Cross-cutting rules&quot;">​</a></h2><ul><li><strong>Multi-tenancy from day one</strong>: <code>org_id</code> and <code>project_id</code> on every table, indexed, even in single-tenant self-host.</li><li><strong>Storage seams</strong>: the span store and the queue sit behind interfaces so columnar storage and a real broker can slot in at scale without touching core.</li><li><strong>Fail open at the edge</strong>: reporters and the GitHub Action never fail a CI job because Flakemetry is unreachable.</li><li><strong>Provider-agnostic AI</strong>: hosted or local models are a config change, never a code change.</li></ul>`,14)])])}const g=a(r,[["render",o]]);export{u as __pageData,g as default};
